def is_valid(grid, row, col, num):
    # Check row
    for i in range(9):
        if grid[row * 9 + i] == num:
            return False
    # Check column
    for i in range(9):
        if grid[i * 9 + col] == num:
            return False
    # Check 3x3 block
    start_row, start_col = 3 * (row // 3), 3 * (col // 3)
    for i in range(3):
        for j in range(3):
            if grid[(start_row + i) * 9 + (start_col + j)] == num:
                return False
    return True

def solve(grid):
    for i in range(81):
        if grid[i] == 0:
            for num in range(1, 10):
                if is_valid(grid, i // 9, i % 9, num):
                    grid[i] = num
                    if solve(grid):
                        return True
                    grid[i] = 0
            return False
    return True

