def is_valid_sudoku(grid):
    # Check rows
    for r in range(9):
        row = [grid[r * 9 + c] for c in range(9)]
        if sorted(row) != list(range(1, 10)):
            return False
    # Check columns
    for c in range(9):
        col = [grid[r * 9 + c] for r in range(9)]
        if sorted(col) != list(range(1, 10)):
            return False
    # Check blocks
    for br in range(3):
        for bc in range(3):
            block = []
            for r in range(3):
                for c in range(3):
                    block.append(grid[(br * 3 + r) * 9 + (bc * 3 + c)])
            if sorted(block) != list(range(1, 10)):
                return False
    return True

